"use client";
/* Gist, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Gist(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("gist"); }, []);
  return React.createElement("piix-pal", { "pal": "gist", ...piixAttrs(props) });
}

export default Gist;
